// static
bool SearchHandlerStubDispatch::Accept(
    SearchHandler* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kSearchHandler_Search_Name: {
      break;
    }
    case internal::kSearchHandler_Update_Name: {
      break;
    }
    case internal::kSearchHandler_Observe_Name: {

      DCHECK(message->is_serialized());
      internal::SearchHandler_Observe_Params_Data* params =
          reinterpret_cast<internal::SearchHandler_Observe_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      ::mojo::PendingRemote<SearchResultsObserver> p_observer{};
      SearchHandler_Observe_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_observer =
            input_data_view.TakeObserver<decltype(p_observer)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            SearchHandler::Name_, 2, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Observe(
std::move(p_observer));
      return true;
    }
  }
  return false;
}

// static
bool SearchHandlerStubDispatch::AcceptWithResponder(
    SearchHandler* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kSearchHandler_Search_Name: {

      internal::SearchHandler_Search_Params_Data* params =
          reinterpret_cast<
              internal::SearchHandler_Search_Params_Data*>(
                  message->mutable_payload());
      
      bool success = true;
      ::std::u16string p_query{};
      uint32_t p_max_num_results{};
      SearchHandler_Search_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadQuery(&p_query))
        success = false;
      if (success)
        p_max_num_results = input_data_view.max_num_results();
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            SearchHandler::Name_, 0, false);
        return false;
      }
      SearchHandler::SearchCallback callback =
          SearchHandler_Search_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Search(
std::move(p_query), 
std::move(p_max_num_results), std::move(callback));
      return true;
    }
    case internal::kSearchHandler_Update_Name: {

      internal::SearchHandler_Update_Params_Data* params =
          reinterpret_cast<
              internal::SearchHandler_Update_Params_Data*>(
                  message->mutable_payload());
      
      bool success = true;
      std::vector<SearchConceptPtr> p_concepts{};
      SearchHandler_Update_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadConcepts(&p_concepts))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            SearchHandler::Name_, 1, false);
        return false;
      }
      SearchHandler::UpdateCallback callback =
          SearchHandler_Update_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Update(
std::move(p_concepts), std::move(callback));
      return true;
    }
    case internal::kSearchHandler_Observe_Name: {
      break;
    }
  }
  return false;
}
