// static
bool StructTraits<::ash::help_app::mojom::SearchResult::DataView, ::ash::help_app::mojom::SearchResultPtr>::Read(
    ::ash::help_app::mojom::SearchResult::DataView input,
    ::ash::help_app::mojom::SearchResultPtr* output) {
  bool success = true;
  ::ash::help_app::mojom::SearchResultPtr result(::ash::help_app::mojom::SearchResult::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadMainCategory(&result->main_category))
        success = false;
      if (success && !input.ReadUrlPathWithParameters(&result->url_path_with_parameters))
        success = false;
      if (success && !input.ReadLocale(&result->locale))
        success = false;
      if (success)
        result->relevance_score = input.relevance_score();
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::ash::help_app::mojom::SearchConcept::DataView, ::ash::help_app::mojom::SearchConceptPtr>::Read(
    ::ash::help_app::mojom::SearchConcept::DataView input,
    ::ash::help_app::mojom::SearchConceptPtr* output) {
  bool success = true;
  ::ash::help_app::mojom::SearchConceptPtr result(::ash::help_app::mojom::SearchConcept::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadMainCategory(&result->main_category))
        success = false;
      if (success && !input.ReadTags(&result->tags))
        success = false;
      if (success && !input.ReadTagLocale(&result->tag_locale))
        success = false;
      if (success && !input.ReadUrlPathWithParameters(&result->url_path_with_parameters))
        success = false;
      if (success && !input.ReadLocale(&result->locale))
        success = false;
  *output = std::move(result);
  return success;
}

